(() => {
  const path = location.pathname;
  const isEs = path.includes('/es/');
  const main = document.querySelector('main');
  if (!main || document.querySelector('[data-accountability-spotlight]')) return;

  const css = document.createElement('style');
  css.textContent = `.ias{padding:2.1rem 0;background:#eef1f2;border-top:1px solid rgba(19,37,45,.12);border-bottom:1px solid rgba(19,37,45,.12)}.ias h2{margin-top:0}.ias-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}.ias-map{display:grid;grid-template-columns:repeat(5,1fr);gap:.55rem}.ias-box{background:#fff;border:1px solid rgba(19,37,45,.15);border-radius:14px;padding:1rem}.ias-box strong{display:block;margin-bottom:.35rem}.ias-arrow{text-align:center;font-weight:900;font-size:1.2rem}.ias-contrast{display:grid;grid-template-columns:1fr auto 1fr;gap:1rem;align-items:stretch}.ias-side{background:#fff;border:1px solid rgba(19,37,45,.15);border-radius:16px;padding:1.15rem}.ias-side b{font-size:1.15rem}.ias-vs{align-self:center;font-weight:900}.ias-quote{font-size:clamp(1.25rem,3vw,2rem);font-weight:900;line-height:1.18;margin:1.2rem 0 0}.ias-table{width:100%;border-collapse:collapse;background:#fff}.ias-table th,.ias-table td{padding:.75rem;border:1px solid rgba(19,37,45,.13);text-align:left;vertical-align:top}.ias-table th{background:#13252d;color:#fff}.ias-families{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem}.ias-family{background:#fff;border:1px solid rgba(19,37,45,.14);border-radius:14px;padding:1rem}.ias-family a{font-weight:800}@media(max-width:850px){.ias-grid,.ias-map,.ias-families{grid-template-columns:1fr}.ias-contrast{grid-template-columns:1fr}.ias-vs{text-align:center}}`;
  document.head.appendChild(css);

  const insertAfterFirst = (node) => {
    const grammar = main.querySelector('[data-accountability-grammar]');
    if (grammar) grammar.insertAdjacentElement('afterend', node);
    else (main.querySelector('section') || main.firstElementChild).insertAdjacentElement('afterend', node);
  };

  const section = document.createElement('section');
  section.className = 'ias';
  section.dataset.accountabilitySpotlight = 'true';

  if (path.includes('mensaje-abierto-cgpj') || path.includes('open-message-cgpj')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">MAPA DE COMPETENCIAS · NO TODO ES “EL CGPJ”</p><h2>La pregunta correcta depende del tipo de problema.</h2><div class="ias-map"><div class="ias-box"><strong>Mérito jurídico</strong>Recursos y tribunales de apelación.</div><div class="ias-box"><strong>Conducta judicial</strong>Promotor / disciplina, dentro de su competencia legal.</div><div class="ias-box"><strong>Funcionamiento del órgano</strong>Servicio de Inspección / Comisión Permanente cuando proceda.</div><div class="ias-box"><strong>LAJ / oficina</strong>Vía jerárquica o revisora propia; no se atribuye automáticamente al juez.</div><div class="ias-box"><strong>Posible delito</strong>Órgano instructor / Ministerio Fiscal, no el CGPJ como tribunal penal.</div></div><p class="ias-quote">No pedimos que el lector crea la alegación. Preguntamos qué comprobó el órgano competente y qué registro lo demuestra.</p><h2 style="margin-top:1.8rem">Alegación o preocupación → registro capaz de comprobarla</h2><table class="ias-table"><thead><tr><th>Cuestión</th><th>Registro / comprobación objetiva</th></tr></thead><tbody><tr><td>Alegaciones sobre acceso o contacto</td><td>Registros oficiales o técnicos disponibles legalmente; expediente CGPJ que muestre si fueron solicitados o valorados.</td></tr><tr><td>Interacción observada en sede judicial</td><td>Acta, agenda, asistencia, grabación o registro oficial disponible; después, explicación contradictoria si procede.</td></tr><tr><td>Qué conocía el órgano judicial</td><td>Índice y escritos incorporados al expediente antes de cada decisión material.</td></tr><tr><td>Demora / funcionamiento</td><td>Cronología procesal y, si existe, informe de Inspección o medida de refuerzo.</td></tr><tr><td>Supervisión del AC</td><td>Petición, informe del AC, oposición y resolución judicial que explique el control ejercido.</td></tr></tbody></table></div>` : `<div class="shell"><p class="kicker">COMPETENCE MAP · NOT EVERYTHING IS “THE CGPJ”</p><h2>The right question depends on the type of issue.</h2><div class="ias-map"><div class="ias-box"><strong>Legal merits</strong>Appeals and appellate courts.</div><div class="ias-box"><strong>Judicial conduct</strong>Disciplinary Promoter / discipline within the lawful remit.</div><div class="ias-box"><strong>Court functioning</strong>Inspection Service / Permanent Commission where applicable.</div><div class="ias-box"><strong>LAJ / court office</strong>Its own hierarchical/review route; not automatically attributed to the judge.</div><div class="ias-box"><strong>Possible crime</strong>Investigating court / Public Prosecution Service, not the CGPJ acting as a criminal court.</div></div><p class="ias-quote">We do not ask the reader to believe the allegation. We ask what the competent body checked and which record proves it.</p><h2 style="margin-top:1.8rem">Concern → official record capable of testing it</h2><table class="ias-table"><thead><tr><th>Issue</th><th>Objective record / check</th></tr></thead><tbody><tr><td>Assertions of access or contact</td><td>Lawfully available official/technical records; CGPJ file showing whether they were requested or assessed.</td></tr><tr><td>Observed courthouse interaction</td><td>Minutes, attendance, diary, recording or other available official record, followed by any contrary explanation.</td></tr><tr><td>What was before the court</td><td>Docket index and filed material preceding each material decision.</td></tr><tr><td>Delay / functioning</td><td>Procedural chronology and any Inspection or reinforcement report if one exists.</td></tr><tr><td>Supervision of the insolvency administrator</td><td>Request, AC report, opposition and judicial decision explaining the control exercised.</td></tr></tbody></table></div>`;
    insertAfterFirst(section); return;
  }

  if (path.includes('cnmv-ricpe-verificacion') || path.includes('cnmv-ricpe-verification')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">LA CONTRADICCIÓN SUPERVISORA EN UNA PANTALLA</p><div class="ias-contrast"><div class="ias-side"><b>SUPERVISIÓN CONFIRMADA</b><p>La propia CNMV confirmó actuaciones supervisoras derivadas de la alerta de enero de 2021.</p></div><div class="ias-vs">Y, A LA VEZ</div><div class="ias-side"><b>DOS DOCUMENTOS DE JULIO DE 2021 NO CONSTABAN EN EL CORPUS LOCALIZADO</b><p>La cuestión no es convertir esa ausencia en negligencia: es saber si esos documentos fueron incorporados después y si su materialidad se reevaluó.</p></div></div></div>` : `<div class="shell"><p class="kicker">THE SUPERVISORY TENSION IN ONE SCREEN</p><div class="ias-contrast"><div class="ias-side"><b>SUPERVISION CONFIRMED</b><p>CNMV itself confirmed supervisory activity following the January 2021 alert.</p></div><div class="ias-vs">AND YET</div><div class="ias-side"><b>TWO JULY-2021 DOCUMENTS WERE NOT IN THE LOCATED SUPERVISORY CORPUS</b><p>The question is not to convert absence into negligence: it is whether those documents were later incorporated and whether their materiality was reassessed.</p></div></div></div>`;
    insertAfterFirst(section); return;
  }

  if (path.includes('concurso-36-2012-laj') || path.includes('insolvency-36-2012-laj')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">OBJETO DE AUDITORÍA</p><h2>Un testimonio debe dejar una cadena reconstruible.</h2><div class="ias-map"><div class="ias-box"><strong>PETICIÓN</strong>Quién pidió qué y para qué.</div><div class="ias-box"><strong>RESOLUCIÓN</strong>Qué autorizó exactamente la oficina.</div><div class="ias-box"><strong>NOTIFICACIÓN</strong>A quién se dio traslado y cuándo.</div><div class="ias-box"><strong>ENTREGA</strong>A quién se entregó y por qué canal.</div><div class="ias-box"><strong>USO EXTERNO</strong>Notaría, Registro, Fiscalía, otro juzgado u otro destino.</div></div></div>` : `<div class="shell"><p class="kicker">AUDIT OBJECT</p><h2>A judicial testimony should leave a reconstructable chain.</h2><div class="ias-map"><div class="ias-box"><strong>REQUEST</strong>Who asked for what and for what stated purpose.</div><div class="ias-box"><strong>ORDER</strong>What the office actually authorised.</div><div class="ias-box"><strong>SERVICE</strong>Who was notified and when.</div><div class="ias-box"><strong>DELIVERY</strong>Who received it and through which channel.</div><div class="ias-box"><strong>EXTERNAL USE</strong>Notary, Registry, prosecution, another court or another destination.</div></div></div>`;
    insertAfterFirst(section); return;
  }

  if (path.includes('administrador-concursal') || path.includes('insolvency-administrator')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">PUENTE CONTABLE QUE DEBE PODER REPRODUCIRSE</p><div class="ias-map"><div class="ias-box"><strong>CRÉDITO</strong>Principal y rango.</div><div class="ias-box"><strong>INTERESES</strong>Base, periodos y cálculo.</div><div class="ias-box"><strong>€400.000 / LOCALES</strong>Tratamiento jurídico y contable.</div><div class="ias-box"><strong>DACIÓN / COMPENSACIÓN</strong>Valor aplicado y cancelaciones.</div><div class="ias-box"><strong>CAJA / SOBRANTE</strong>Pagos, costes, remuneración y saldo final.</div></div></div>` : `<div class="shell"><p class="kicker">ACCOUNTING BRIDGE THAT SHOULD BE REPRODUCIBLE</p><div class="ias-map"><div class="ias-box"><strong>CREDIT</strong>Principal and ranking.</div><div class="ias-box"><strong>INTEREST</strong>Basis, periods and calculation.</div><div class="ias-box"><strong>€400,000 / UNITS</strong>Legal and accounting treatment.</div><div class="ias-box"><strong>DATION / SET-OFF</strong>Value applied and cancellations.</div><div class="ias-box"><strong>CASH / SURPLUS</strong>Payments, costs, remuneration and final balance.</div></div></div>`;
    insertAfterFirst(section); return;
  }

  if (path.includes('cabildo-lanzarote-turismo')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">DISTINCIÓN CENTRAL</p><div class="ias-contrast"><div class="ias-side"><b>UNIDAD DE EXPLOTACIÓN</b><p>Una administración turística puede trabajar con un establecimiento económicamente unitario.</p></div><div class="ias-vs">≠</div><div class="ias-side"><b>UNIDAD DE PROPIEDAD</b><p>Eso no demuestra por sí solo que todas las fincas pertenezcan al mismo titular ni que desaparezcan derechos de terceros.</p></div></div></div>` : `<div class="shell"><p class="kicker">CENTRAL DISTINCTION</p><div class="ias-contrast"><div class="ias-side"><b>OPERATING UNITY</b><p>A tourism authority may deal with an economically unitary establishment.</p></div><div class="ias-vs">≠</div><div class="ias-side"><b>OWNERSHIP UNITY</b><p>That does not by itself prove that all registered units share one owner or erase third-party rights.</p></div></div></div>`;
    insertAfterFirst(section); return;
  }

  if (path.includes('quien-debe-responder-que') || path.includes('who-should-answer-what')) {
    section.innerHTML = isEs ? `<div class="shell"><p class="kicker">MAPA DEL SISTEMA</p><h2>No todos responden por lo mismo.</h2><div class="ias-families"><div class="ias-family"><strong>JUSTICIA / GOBIERNO</strong><p>Juez · LAJ · AC · AP4 · CGPJ · Ministerio Fiscal · DP 1901</p></div><div class="ias-family"><strong>INVERSIÓN / SUPERVISIÓN</strong><p>RICPE · CNMV</p></div><div class="ias-family"><strong>DINERO PÚBLICO / INTEGRIDAD</strong><p>Intervención · SNCA/IGAE · Fondos UE · AEAT/ATC</p></div><div class="ias-family"><strong>LOCAL / TURISMO / PROPIEDAD</strong><p>Yaiza · Cabildo/Turismo · Gobierno de Canarias Turismo · perímetro privado</p></div></div><p class="ias-quote">La pregunta útil no es “¿quién tiene la culpa?”, sino “¿qué función tenía cada uno, qué registro recibió, qué comprobó y qué puede hacer ahora?”</p></div>` : `<div class="shell"><p class="kicker">SYSTEM MAP</p><h2>Different bodies answer different questions.</h2><div class="ias-families"><div class="ias-family"><strong>JUSTICE / GOVERNANCE</strong><p>Judge · LAJ · AC · AP4 · CGPJ · Public Prosecution Service · DP 1901</p></div><div class="ias-family"><strong>INVESTMENT / SUPERVISION</strong><p>RICPE · CNMV</p></div><div class="ias-family"><strong>PUBLIC MONEY / INTEGRITY</strong><p>Intervención · SNCA/IGAE · EU funds · AEAT/ATC</p></div><div class="ias-family"><strong>LOCAL / TOURISM / PROPERTY</strong><p>Yaiza · Cabildo/Tourism · Canary Islands Tourism · private perimeter</p></div></div><p class="ias-quote">The useful question is not “who is to blame?” but “what function did each actor hold, what record did they receive, what did they check, and what can they do now?”</p></div>`;
    insertAfterFirst(section); return;
  }
})();